keyConcepts.codeExample:
-- Empêche les doublons d'email, y compris sous concurrence
ALTER TABLE customers
  ADD CONSTRAINT customers_email_unique UNIQUE (email);

-- Empêche les statuts invalides d'entrer en base
ALTER TABLE orders
  ADD CONSTRAINT orders_status_check
  CHECK (status IN ('pending', 'paid', 'shipped', 'cancelled'));

-- Cette insertion échoue désormais au lieu de corrompre les données
INSERT INTO orders (customer_id, status, total_cents)
VALUES (42, 'shiped', 1999);
